<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#17231d;font-size:11px}h1{font-size:22px;margin:0 0 4px}.meta{color:#65736b;margin-bottom:20px}table.data{width:100%;border-collapse:collapse}.data th,.data td{border:1px solid #dce3de;padding:7px;text-align:left}.data th{background:#eef4ef;text-transform:uppercase;font-size:9px}.totals{width:40%;margin-top:16px;margin-left:auto}.totals td{border:1px solid #dce3de;padding:7px}.totals td.grand{font-weight:bold;background:#eef4ef}footer{position:fixed;bottom:0;color:#78847d;font-size:9px}</style></head><body><h1>Invoice {{ $invoice->invoice_no }}</h1><div class="meta">{{ $invoice->tenant?->name ?? 'Tenant #'.$invoice->tenant_id }} · Status: {{ strtoupper($invoice->status) }} · Diterbitkan {{ optional($invoice->issued_at)->format('d-m-Y H:i') }}</div><table class="data"><thead><tr><th>Deskripsi</th><th>Qty</th><th>Harga Satuan</th><th>Jumlah</th></tr></thead><tbody>@forelse($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ rtrim(rtrim(number_format((float) $item->quantity, 3, '.', ''), '0'), '.') }}</td><td>Rp {{ number_format((float) $item->unit_price, 2, ',', '.') }}</td><td>Rp {{ number_format((float) $item->amount, 2, ',', '.') }}</td></tr>@empty<tr><td colspan="4">Tidak ada item.</td></tr>@endforelse</tbody></table><table class="totals"><tr><td>Subtotal</td><td>Rp {{ number_format((float) $invoice->subtotal, 2, ',', '.') }}</td></tr><tr><td>Diskon</td><td>Rp {{ number_format((float) $invoice->discount, 2, ',', '.') }}</td></tr><tr><td>Pajak</td><td>Rp {{ number_format((float) $invoice->tax, 2, ',', '.') }}</td></tr><tr><td class="grand">Total ({{ $invoice->currency }})</td><td class="grand">Rp {{ number_format((float) $invoice->total, 2, ',', '.') }}</td></tr></table><footer>Dibuat oleh PanduPOS pada {{ now()->format('d-m-Y H:i') }}</footer></body></html>